	if err := json.Unmarshal(planOutput.Bytes(), &reviewed); err != nil {
		t.Fatalf("decode read-only terminal plan: %v", err)
	}
	if reviewed.DisposableWorkload || reviewed.AcknowledgePermanentDataLoss || reviewed.AuthorizeForcedStop ||
