		t.Fatalf("terminal plan omitted exact resources or enabled consent: %+v", reviewed)
	}
	reviewed.DisposableWorkload = true
	reviewed.AcknowledgePermanentDataLoss = true
	reviewed.AuthorizeForcedStop = true
