}

placement_apply.text:
func servePlacementAdmission(ctx context.Context, conn *nats.Conn, cell string, policy signerPolicy, control *authority.Runtime, material ...placementMaterialAdmission) (*nats.Subscription, error) {
	return serveManagedAdmissionKind(ctx, conn, cell, managedKindPlacement, func(ctx context.Context, message *nats.Msg) {
		if len(message.Data) > maxPlacementWireBytes || !control.Current().CanMutate() {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		defer cancel()
		response, err := verifyAndApplyPlacement(requestCtx, message.Data, cell, policy, control, material...)
		if errors.Is(err, authority.ErrFenced) || errors.Is(err, authority.ErrNotLeader) || !control.Current().CanMutate() {
			return
		}
		if err != nil {
			response = placementApplyResponse{Error: err.Error()}
		}
		wire, err := json.Marshal(response)
		if err == nil {
			_ = message.Respond(wire)
		}
	})
}

func verifyAndApplyPlacement(ctx context.Context, wire []byte, cell string, policy signerPolicy, control placementAdmissionControl, material ...placementMaterialAdmission) (placementApplyResponse, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxPlacementWireBytes); err != nil {
		return placementApplyResponse{}, err
	}
	var intent placement.Intent
	if err := protocol.DecodeStrict(envelope.Payload, &intent, maxPlacementIntentBytes); err != nil {
		return placementApplyResponse{}, err
	}
	if err := intent.ValidateForAdmission(); err != nil {
		return placementApplyResponse{}, err
	}
	if !intentSelectsCell(intent, cell) {
		return placementApplyResponse{}, errors.New("placement intent does not select this regional cell")
	}
	grant, exists := policy.grant(envelope.Actor)
	if !exists || !grant.CanPlaceTerraBase {
		return placementApplyResponse{}, errors.New("placement actor is unauthorized")
	}
	trusted, exists := policy.trusted(envelope.KeyID)
	if !exists || trusted.Actor != envelope.Actor {
		return placementApplyResponse{}, errors.New("placement signing key is untrusted")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{
		Region: cell, Kind: managedKindPlacement, Actor: trusted.Actor,
		OperationID: placementOperationID(intent), Generation: intent.Generation, Epoch: envelope.Epoch,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: 5 * time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return placementApplyResponse{}, err
	}
	if envelope.Epoch == 0 || control.Current().Epoch != envelope.Epoch {
		return placementApplyResponse{}, authority.ErrFenced
	}
	payload, err := protocol.EncodeJSON(intent)
	if err != nil {
		return placementApplyResponse{}, err
	}
	if !bytes.Equal(envelope.Payload, payload) {
		return placementApplyResponse{}, errors.New("signed placement payload is not canonical")
	}
	if len(material) > 1 {
		return placementApplyResponse{}, errors.New("multiple managed material verifiers")
	}
	if len(material) == 1 {
		if material[0] == nil {
			return placementApplyResponse{}, errors.New("managed material verifier is unavailable")
		}
		if err := material[0](ctx, intent); err != nil {
			return placementApplyResponse{}, fmt.Errorf("verify committed managed material: %w", err)
		}
	}
	for range 8 {
		if _, err := control.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			return placementApplyResponse{}, authority.ErrFenced
		} else if !errors.Is(err, authority.ErrNotFound) {
			return placementApplyResponse{}, err
		}
		current, err := control.ReadPlacementIntent(ctx, intent.DatabaseID, intent.PartitionID)
		if err == nil {
			old, err := placement.DecodeCommittedIntent(current.Payload)
			if err != nil || old.DatabaseID != intent.DatabaseID || old.PartitionID != intent.PartitionID {
				return placementApplyResponse{}, errors.New("durable placement intent is corrupt")
			}
			if old.Generation != intent.Generation || !bytes.Equal(current.Payload, payload) {
				return placementApplyResponse{}, authority.ErrConflict
			}
			sequence, err := control.ConfirmActivePlacementIntent(ctx, envelope.Epoch, intent.DatabaseID, intent.PartitionID, payload)
			if err != nil {
				return placementApplyResponse{}, err
			}
			return placementApplyResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, Generation: intent.Generation, Sequence: sequence}, nil
		} else if !errors.Is(err, authority.ErrNotFound) {
			return placementApplyResponse{}, err
		}
		sequence, err := control.CommitPlacementIntent(ctx, envelope.Epoch, intent.DatabaseID, intent.PartitionID, placementOperationID(intent), 0, payload)
		if err == nil {
			return placementApplyResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, Generation: intent.Generation, Sequence: sequence}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return placementApplyResponse{}, err
		}
	}

native_ready.text:
func nativeReady(statuses []host.HostStatus, desired []host.Desired, intent delivery.Intent, now time.Time) ([]string, error) {
	expected := map[string]host.Desired{}
	for _, d := range desired {
		if d.Cell != intent.Cell || d.Role != intent.Role || d.Environment != intent.Environment || d.Withdrawn {
			continue
		}
		if _, duplicate := expected[d.Node]; duplicate {
			return nil, errors.New("duplicate expected native node")
		}
		if d.Digest != intent.ArtifactDigest || d.Generation != intent.Generation && workload.ReleaseOf(d.Generation) != intent.Generation ||
			delivery.ConfigDigestOf(d.Args, d.Env, d.Secrets) != intent.ConfigDigest {
			return nil, nil
		}
		expected[d.Node] = d
	}
	if len(expected) != intent.DesiredReplicas || len(expected) == 0 {
		return nil, nil
	}
	seen := map[string]bool{}
	for _, status := range statuses {
		r := status.Registration
		d, ok := expected[r.Node]
		if !ok {
			continue
		}
		if seen[r.Node] {
			return nil, errors.New("duplicate native host status")
		}
		seen[r.Node] = true
		if !status.Verified || status.Retired || !status.SessionExpiresAt.After(now) || r.Cell != intent.Cell || r.Environment != intent.Environment || !slices.Contains(r.Roles, intent.Role) {
			return nil, nil
		}
		matches := 0
		for _, report := range status.Reports {
			if report.Role != intent.Role {
				continue
			}
			matches++
			if matches > 1 {
				return nil, errors.New("duplicate native report")
			}
			if report.Cell != intent.Cell || report.Node != d.Node || report.Environment != intent.Environment || report.Digest != d.Digest || report.Generation != d.Generation ||
				report.SessionID == "" || report.Epoch == 0 || report.ObservedAt.IsZero() || report.ObservedAt.After(now) || now.Sub(report.ObservedAt) >= host.ReportMaxAge {
				return nil, nil
			}
			if report.State == "failed" {
				return nil, fmt.Errorf("%w: %s replica %s failed: %s", errBadRelease, intent.Role, report.Node, report.Error)
			}
			if report.State != "running" {
				return nil, nil
			}
		}
		if matches != 1 {
			return nil, nil
		}
	}
	if len(seen) != len(expected) {
		return nil, nil
	}
	return slices.Sorted(maps.Keys(expected)), nil
}

terminal_request.text:
func requestTerminal(ctx context.Context, cfg Config, runtime *natscell.Runtime,
	action, operationID string, generation uint64, payload any,
) (terminalReply, error) {
	policy, err := terminalOperatorCodec(cfg)
	if err != nil {
		return terminalReply{}, err
	}
	codec, err := policy.withOperator(cfg.Operator)
	if err != nil {
		return terminalReply{}, err
	}
	epoch, err := observeOperatorAuthority(ctx, func(callCtx context.Context) (authority.Snapshot, error) {
		return authority.Observe(callCtx, runtime.JetStream(), cfg.NATS.Cell)
	})
	if err != nil {
		return terminalReply{}, err
	}
	encoded, err := protocol.EncodeJSON(payload)
	if err != nil || len(encoded) > maxTerminalPayloadBytes {
		return terminalReply{}, errors.New("terminal request payload is too large")
	}
	now := time.Now().UTC()
	envelope, err := protocol.SignEnvelope(encoded, protocol.EnvelopeScope{
		Region: cfg.NATS.Cell, Kind: "placement.terminal." + action, Actor: cfg.Operator.Actor,
		OperationID: operationID, Generation: generation, Epoch: epoch,
	}, now, now.Add(5*time.Minute), codec.PrivateKey)
	if err != nil {
		return terminalReply{}, err
	}
	wire, err := protocol.EncodeJSON(envelope)
	if err != nil {
		return terminalReply{}, err
	}
	requestCtx, cancel := context.WithTimeout(ctx, 45*time.Second)
	defer cancel()
	message, err := runtime.Conn().RequestWithContext(requestCtx, terminalSubject(cfg.NATS.Cell, action), wire)
	if err != nil {
		return terminalReply{}, fmt.Errorf("request terminal %s: %w", action, err)
	}
	var reply terminalReply
	if err := protocol.DecodeStrict(message.Data, &reply, maxTerminalWireBytes); err != nil {
		return terminalReply{}, err
	}
	if reply.Error != "" {
		return terminalReply{}, errors.New(reply.Error)
	}
	return reply, nil
}

terminal_serve.text:
func serveTerminalAdmission(ctx context.Context, conn *nats.Conn, cell string, policy signerPolicy,
	control *authority.Runtime, region oci.RegionConfig, members placement.Store,
	inventory oci.TerminalExecutor, fence terminalGrantFence, proof terminalGrantProof,
	grants terminalGrantStatus,
) (*nats.Subscription, error) {
	if control == nil || members == nil || inventory == nil || fence == nil || proof == nil || grants == nil ||
		!strings.EqualFold(string(region.Region), cell) {
		return nil, errors.New("terminal admission requires bound authority, placement, and OCI inventory")
	}
	return conn.Subscribe(terminalSubject(cell, ">"), func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) == 0 || len(message.Data) > maxTerminalWireBytes ||
			!control.Current().CanMutate() {
			return
		}
		var action string
		for _, candidate := range []string{"plan", "apply", "status"} {
			if message.Subject == terminalSubject(cell, candidate) {
				action = candidate
				break
			}
		}
		if action == "" {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, 40*time.Second)
		defer cancel()
		reply, err := handleTerminalRequest(requestCtx, message.Data, action, cell, policy,
			control, region, members, inventory, fence, proof, grants)
		if errors.Is(err, authority.ErrFenced) || errors.Is(err, authority.ErrNotLeader) ||
			!control.Current().CanMutate() {
			return
		}
		if err != nil {
			reply = terminalReply{Error: err.Error()}
		}
		encoded, err := protocol.EncodeJSON(reply)
		if err == nil {
			_ = message.Respond(encoded)
		}
	})
}

terminal_handle.text:
func handleTerminalRequest(ctx context.Context, wire []byte, action, cell string, policy signerPolicy,
	control terminalAdmissionControl, region oci.RegionConfig, members terminalAdmissionMembers,
	inventory oci.TerminalExecutor, fence terminalGrantFence, proof terminalGrantProof,
	grants terminalGrantStatus,
) (terminalReply, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxTerminalWireBytes); err != nil {
		return terminalReply{}, err
	}
	var request terminalRequest
	var intent authority.TerminalIntent
	var operationID string
	var generation uint64 = 1
	if action == "apply" {
		if err := protocol.DecodeStrict(envelope.Payload, &intent, maxTerminalPayloadBytes); err != nil || intent.Validate() != nil {
			return terminalReply{}, errors.New("terminal apply payload is invalid")
		}
		operationID, generation = intent.OperationID, intent.PlacementGeneration
		request = terminalRequest{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
			OperationID: intent.OperationID, Nonce: intent.Nonce}
	} else {
		if action != "plan" && action != "status" {
			return terminalReply{}, errors.New("unknown terminal request")
		}
		if err := protocol.DecodeStrict(envelope.Payload, &request, maxTerminalPayloadBytes); err != nil ||
			!validTerminalRequest(request) {
			return terminalReply{}, errors.New("terminal request scope is invalid")
		}
		operationID = request.OperationID
	}
	grant, ok := policy.grant(envelope.Actor)
	trusted, trustedOK := policy.trusted(envelope.KeyID)
	if !ok || !grant.CanTeardownTerraBase || !trustedOK || trusted.Actor != envelope.Actor {
		return terminalReply{}, errors.New("terminal signing actor is unauthorized")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{
		Region: cell, Kind: "placement.terminal." + action, Actor: trusted.Actor,
		OperationID: operationID, Generation: generation, Epoch: envelope.Epoch,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{
		MaxLifetime: 5 * time.Minute, ClockSkew: 30 * time.Second,
	}); err != nil {
		return terminalReply{}, err
	}
	if envelope.Epoch == 0 || control.Current().Epoch != envelope.Epoch {
		return terminalReply{}, authority.ErrFenced
	}
	canonical, err := protocol.EncodeJSON(request)
	if action == "apply" {
		canonical, err = protocol.EncodeJSON(intent)
	}
	if err != nil || !bytes.Equal(canonical, envelope.Payload) {
		return terminalReply{}, errors.New("terminal request payload is not canonical")
	}
	scope := authority.WorkloadScope{DatabaseID: request.DatabaseID, PartitionID: request.PartitionID}
	if action == "status" {
		entry, err := control.ReadTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID)
		if err != nil {
			return terminalReply{}, err
		}
		accepted, err := decodeCurrentTerminal(entry, scope.DatabaseID, scope.PartitionID)
		if err != nil {
			return terminalReply{}, err
		}
		status, err := inventory.InspectTerminalStatus(ctx, accepted)
		if err != nil {
			return terminalReply{}, err
		}
		if status.Phase == "complete" {
			if grants == nil || grants(ctx, accepted) != nil {
				status.Phase = "held"
				status.Pending = append(status.Pending, "terminal enrollment grant readback incomplete")
			}
		}
		return terminalReply{Intent: &accepted, MarkerSequence: entry.Sequence, Status: &status}, nil
	}
	if action == "apply" {
		prior, err := control.ReadTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID)
		if err == nil {
			if prior.OperationID == intent.OperationID && bytes.Equal(prior.Payload, envelope.Payload) {
				return terminalReply{Intent: &intent, MarkerSequence: prior.Sequence}, nil
			}
			return terminalReply{}, authority.ErrOperationConflict
		}
		if !errors.Is(err, authority.ErrNotFound) {
			return terminalReply{}, err
		}
	}
	planned, err := buildTerminalPlan(ctx, cell, region, members, inventory, control, request)
	if err != nil {
		return terminalReply{}, err
	}
	if action == "plan" {
		planned.DisposableWorkload = false
		planned.AcknowledgePermanentDataLoss = false
		planned.AuthorizeForcedStop = false
		return terminalReply{Intent: &planned}, nil
	}
	plannedBytes, err := protocol.EncodeJSON(planned)
	if err != nil || !bytes.Equal(plannedBytes, envelope.Payload) {
		return terminalReply{}, errors.New("signed terminal cleanup differs from current admitted inventory")
	}
	if fence == nil || proof == nil || grants == nil {
		return terminalReply{}, errors.New("terminal enrollment grant fencing is unavailable")
	}
	if err := fence(ctx, envelope.Epoch, intent); err != nil {
		return terminalReply{}, fmt.Errorf("terminal cleanup held during grant fencing; some exact grants may already be disabled: %w", err)
	}
	sequence, err := control.CommitTerminalIntent(ctx, envelope.Epoch, scope, intent.OperationID, envelope.Payload,
		func(lockedCtx context.Context) error {
			pending, err := control.ListPendingEnrollmentEffects(lockedCtx, scope)
			if err != nil {
				return err
			}
			if len(pending) != 0 {
				return errors.New("terminal admission is held by unsettled enrollment grant effects")
			}
			latest, err := buildTerminalPlan(lockedCtx, cell, region, members, inventory, control, request)
			if err != nil {
				return err
			}
			latestBytes, err := protocol.EncodeJSON(latest)
			if err != nil || !bytes.Equal(latestBytes, envelope.Payload) {
				return errors.New("terminal inventory changed before durable admission")
			}
			if err := proof(lockedCtx, intent); err != nil {
				return fmt.Errorf("terminal enrollment grant fence readback: %w", err)
			}
			return inventory.VerifyTerminalInventorySettled(lockedCtx, intent)
		})
	if err != nil {
		return terminalReply{}, fmt.Errorf("terminal cleanup held after exact grant fencing; retry the reviewed intent: %w", err)
	}
	return terminalReply{Intent: &intent, MarkerSequence: sequence}, nil
}

terminal_plan.text:
func buildTerminalPlan(ctx context.Context, cell string, region oci.RegionConfig,
	members terminalAdmissionMembers, inventory oci.TerminalExecutor,
	control terminalAdmissionControl, request terminalRequest,
) (authority.TerminalIntent, error) {
	if !validTerminalRequest(request) || !strings.EqualFold(string(region.Region), cell) {
		return authority.TerminalIntent{}, errors.New("terminal plan has invalid scope or region")
	}
	if _, err := control.ReadTerminalIntent(ctx, request.DatabaseID, request.PartitionID); err == nil {
		return authority.TerminalIntent{}, authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return authority.TerminalIntent{}, err
	}
	entry, err := control.ReadPlacementIntent(ctx, request.DatabaseID, request.PartitionID)
	if err != nil {
		return authority.TerminalIntent{}, err
	}
	admitted, err := placement.DecodeCommittedIntent(entry.Payload)
	if err != nil || admitted.ValidateForAdmission() != nil || admitted.DatabaseID != request.DatabaseID ||
		admitted.PartitionID != request.PartitionID || !intentSelectsCell(admitted, cell) {
		return authority.TerminalIntent{}, errors.New("current placement is not an admitted managed workload")
	}
	states, err := members.ListMembers(ctx, request.DatabaseID, request.PartitionID)
	if err != nil {
		return authority.TerminalIntent{}, err
	}
	targets, err := placement.TerminalTargetsForRegion(admitted, region.Region, region.FaultDomains, states)
	if err != nil {
		return authority.TerminalIntent{}, err
	}
	planned := authority.TerminalIntent{Cell: cell, DatabaseID: request.DatabaseID,
		PartitionID: request.PartitionID, Region: string(region.Region), Owner: region.Owner,
		CompartmentID: region.CompartmentID, FleetGeneration: region.Generation,
		PlacementGeneration: admitted.Generation, PlacementPayloadDigest: admitted.PayloadDigest(),
		OperationID: request.OperationID, Nonce: request.Nonce, Targets: targets,
		DisposableWorkload: true, AcknowledgePermanentDataLoss: true, AuthorizeForcedStop: true}
	if err := planned.Validate(); err != nil {
		return authority.TerminalIntent{}, err
	}
	discovered, err := inventory.DiscoverTerminalTargets(ctx, planned)
	if err != nil {
		return authority.TerminalIntent{}, err
	}
	if len(discovered) != len(targets) {
		return authority.TerminalIntent{}, errors.New("terminal discovery returned a different seat count")
	}
	for index, target := range targets {
		found := discovered[index]
		if found.SeatID != target.SeatID || found.MemberID != target.MemberID ||
			found.HostCreateKey != target.HostCreateKey || found.DataCreateKey != target.DataCreateKey {
			return authority.TerminalIntent{}, errors.New("terminal discovery changed an admitted target")
		}
	}
	for _, member := range states {
		index := slices.IndexFunc(discovered, func(target authority.TerminalTarget) bool {
			return target.SeatID == member.State.MemberID
		})
		if index < 0 || member.State.InstanceID != "" && member.State.InstanceID != discovered[index].InstanceID ||
			member.State.VolumeID != "" && member.State.VolumeID != discovered[index].DataVolumeID {
			return authority.TerminalIntent{}, errors.New("terminal discovery differs from durable placement member")
		}
	}
	planned.Targets = discovered
	if err := planned.Validate(); err != nil {
		return authority.TerminalIntent{}, err
	}
	return planned, nil
}

terminal_decode.text:
func decodeCurrentTerminal(entry authority.LogEntry, databaseID, partitionID string) (authority.TerminalIntent, error) {
	var intent authority.TerminalIntent
	if entry.Kind != authority.MutationTerminalIntent || entry.SubjectKey != databaseID+"."+partitionID ||
		entry.Sequence == 0 || entry.Epoch == 0 || len(entry.Payload) == 0 ||
		json.Unmarshal(entry.Payload, &intent, json.RejectUnknownMembers(true)) != nil ||
		intent.Validate() != nil || intent.DatabaseID != databaseID || intent.PartitionID != partitionID ||
		intent.OperationID != entry.OperationID {
		return authority.TerminalIntent{}, errors.New("current terminal marker has an invalid workload binding")
	}
	return intent, nil
}

terminal_runtime.text:
func (runtime *managedTerminalRuntime) reconcile(ctx context.Context) error {
	if !runtime.control.Current().CanMutate() {
		return nil
	}
	intents, err := runtime.placements.ListIntents(ctx)
	if err != nil {
		return fmt.Errorf("list admitted placement intents for terminal replay: %w", err)
	}
	var failures []error
	for _, placementIntent := range intents {
		entry, err := runtime.control.ReadTerminalIntent(ctx, placementIntent.DatabaseID, placementIntent.PartitionID)
		if errors.Is(err, authority.ErrNotFound) {
			continue
		}
		if err != nil {
			failures = append(failures, err)
			continue
		}
		intent, err := decodeCurrentTerminal(entry, placementIntent.DatabaseID, placementIntent.PartitionID)
		if err != nil {
			failures = append(failures, err)
			continue
		}
		if err := runtime.reconcileIntent(ctx, intent, entry.Sequence); err != nil {
			failures = append(failures, err)
		}
	}
	return errors.Join(failures...)
}

func decodeCurrentTerminal(entry authority.LogEntry, databaseID, partitionID string) (authority.TerminalIntent, error) {
	var intent authority.TerminalIntent
	if entry.Kind != authority.MutationTerminalIntent || entry.SubjectKey != databaseID+"."+partitionID ||
		entry.Sequence == 0 || entry.Epoch == 0 || len(entry.Payload) == 0 ||
		json.Unmarshal(entry.Payload, &intent, json.RejectUnknownMembers(true)) != nil ||
		intent.Validate() != nil || intent.DatabaseID != databaseID || intent.PartitionID != partitionID ||
		intent.OperationID != entry.OperationID {
		return authority.TerminalIntent{}, errors.New("current terminal marker has an invalid workload binding")
	}
	return intent, nil
}

func (runtime *managedTerminalRuntime) reconcileIntent(ctx context.Context, intent authority.TerminalIntent,
	markerSequence uint64,
) error {
	if runtime.hosts != nil {
		if err := runtime.withdrawActiveDesired(ctx, intent); err != nil {
			slog.WarnContext(ctx, "managed terminal optional desired withdrawal failed", observability.ComponentKey, "terminal",
				"database", intent.DatabaseID, "partition", intent.PartitionID, "error", err)
		}
	}
	status, err := runtime.executor.ReconcileTerminal(ctx, intent, markerSequence)
	if err != nil {
		return fmt.Errorf("reconcile exact terminal OCI inventory %s/%s: %w", intent.DatabaseID, intent.PartitionID, err)
	}
	if status.Phase != "complete" {
		return nil
	}
	if runtime.enrollment == nil {
		return errors.New("terminal teardown cannot confirm enrollment grants without the enrollment store")
	}
	snapshot := runtime.control.Current()
	if !snapshot.CanMutate() || snapshot.Epoch == 0 {
		return authority.ErrNotLeader
	}
	return runtime.enrollment.verifyTerminalGrants(ctx, intent)
}

terminal_fake.text:
type terminalTestControl struct {
	*placementAdmissionTestControl
	pending []authority.EnrollmentEffect
}

func (control terminalTestControl) ListPendingEnrollmentEffects(context.Context, authority.WorkloadScope) ([]authority.EnrollmentEffect, error) {
	return control.pending, nil
}

func (control terminalTestControl) CommitTerminalIntent(ctx context.Context, epoch uint64,
	scope authority.WorkloadScope, operationID string, payload []byte, settled func(context.Context) error,
) (uint64, error) {
	if epoch != control.snapshot.Epoch {
		return 0, authority.ErrFenced
	}
	key := scope.DatabaseID + "." + scope.PartitionID
	if _, exists := control.terminal[key]; exists {
		return 0, authority.ErrOperationConflict
	}
	if err := settled(ctx); err != nil {
		return 0, err
	}
	control.nextSeq++
	control.terminal[key] = authority.LogEntry{Kind: authority.MutationTerminalIntent,
		SubjectKey: key, OperationID: operationID, Epoch: epoch, Sequence: control.nextSeq,
		Payload: bytes.Clone(payload)}
	return control.nextSeq, nil
}

type terminalTestMembers struct {
	states []placement.VersionedMemberState
}

func (members terminalTestMembers) ListMembers(context.Context, string, string) ([]placement.VersionedMemberState, error) {
	return members.states, nil
}

type terminalTestInventory struct{ verifies int }

func (*terminalTestInventory) DiscoverTerminalTargets(_ context.Context, intent authority.TerminalIntent) ([]authority.TerminalTarget, error) {
	return intent.Targets, nil
}

func (inventory *terminalTestInventory) VerifyTerminalInventorySettled(_ context.Context, intent authority.TerminalIntent) error {
	inventory.verifies++
	return intent.Validate()
}

func (*terminalTestInventory) InspectTerminalStatus(context.Context, authority.TerminalIntent) (oci.TerminalStatus, error) {
	return oci.TerminalStatus{Phase: "complete"}, nil
}

