func OpenGrantStore(ctx context.Context, js jetstream.JetStream, replicas int) (*GrantStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("host enrollment requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: GrantBucket, History: 2, MaxValueSize: MaxGrantBytes,
		MaxBytes: 64 << 20, Storage: jetstream.FileStorage, Replicas: replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open host enrollment grants: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil || status.Config().Replicas != replicas {
		return nil, errors.New("host enrollment grant replication differs from regional quorum")
	}
	return &GrantStore{kv: kv, js: js}, nil
}

grant_claim.text:
func (store *GrantStore) Claim(ctx context.Context, candidate Grant) (Grant, uint64, error) {
	if store == nil || store.kv == nil || candidate.SchemaVersion != 1 || candidate.InstanceID == "" ||
		!entityid.Valid(candidate.CreateKey) || len(candidate.DescriptorSHA256) != 64 ||
		len(candidate.Request) == 0 || len(candidate.Request) > 16<<10 || len(candidate.Response) != 0 || candidate.Disabled ||
		candidate.OwnerToken != "" || !candidate.LeaseUntil.IsZero() || candidate.IdentityResetOperationID != "" || candidate.SwarmMembership != nil {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant candidate is invalid"))
	}
	claimToken := make([]byte, 32)
	if _, err := rand.Read(claimToken); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	candidate.OwnerToken = base64.RawURLEncoding.EncodeToString(claimToken)
	candidate.LeaseUntil = time.Now().UTC().Add(time.Minute)
	wire, err := json.Marshal(candidate)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	key := grantKey(candidate.InstanceID)
	if revision, err := store.kv.Create(ctx, key, wire); err == nil {
		return candidate, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return Grant{}, 0, fmt.Errorf("create host enrollment grant: %w", err)
	}
	entry, err := store.kv.Get(ctx, key)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(fmt.Errorf("read host enrollment grant: %w", err))
	}
	var current Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &current, json.RejectUnknownMembers(true)) != nil ||
		current.SchemaVersion != 1 || current.InstanceID != candidate.InstanceID || current.CreateKey != candidate.CreateKey ||
		current.DescriptorSHA256 != candidate.DescriptorSHA256 || !bytes.Equal(current.Request, candidate.Request) || current.Disabled {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant differs from the immutable first request or is disabled"))
	}
	if len(current.Response) != 0 {
		return current, entry.Revision(), nil
	}
	if time.Now().Before(current.LeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	current.OwnerToken = candidate.OwnerToken
	current.LeaseUntil = candidate.LeaseUntil
	wire, err = json.Marshal(current)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	revision, err := store.kv.Update(ctx, key, wire, entry.Revision())
	if err != nil {
		wrapped := fmt.Errorf("recover host enrollment grant ownership: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return current, revision, nil
}

grant_read.text:
func (store *GrantStore) Read(ctx context.Context, instanceID string) (Grant, uint64, error) {
	if store == nil || store.kv == nil || instanceID == "" {
		return Grant{}, 0, errors.New("host enrollment grant store is unavailable")
	}
	entry, err := store.kv.Get(ctx, grantKey(instanceID))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &grant, json.RejectUnknownMembers(true)) != nil || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("host enrollment grant is corrupt")
	}
	return grant, entry.Revision(), nil
}

grant_fence.text:
func (enrollment *managedHostEnrollment) fenceTerminalGrants(ctx context.Context, epoch uint64,
	intent authority.TerminalIntent,
) error {
	if enrollment == nil || enrollment.grants == nil || enrollment.members == nil {
		return errors.New("managed terminal grant fencing is unavailable")
	}
	if err := enrollment.validateTerminalGrantIntent(intent); err != nil {
		return err
	}
	if epoch == 0 || enrollment.fencer.Current().Epoch != epoch {
		return authority.ErrFenced
	}
	reader, ok := enrollment.fencer.(authority.TerminalIntentReader)
	if !ok {
		return errors.New("terminal grant fencing requires authority marker access")
	}
	if _, err := reader.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
		return authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	for _, target := range intent.Targets {
		if target.InstanceID == "" {
			continue
		}
		fenced := false
		for range 4 {
			if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
				return err
			}
			grant, revision, err := enrollment.grants.Read(ctx, target.InstanceID)
			if errors.Is(err, jetstream.ErrKeyNotFound) {
				expected := hostenroll.Grant{SchemaVersion: 1,
					InstanceID: target.InstanceID, CreateKey: target.HostCreateKey}
				_, _, err = enrollment.grants.TerminalFence(ctx, expected, 0, intent.OperationID)
				if errors.Is(err, hostenroll.ErrTerminalFenceConflict) {
					continue
				}
				if err != nil {
					return fmt.Errorf("create terminal grant tombstone for seat %s: %w", target.SeatID, err)
				}
			} else if err != nil {
				return fmt.Errorf("read terminal grant for seat %s: %w", target.SeatID, err)
			} else {
				if !isTerminalGrantTombstone(grant, target, intent.OperationID) {
					if err := enrollment.verifyTerminalGrantBinding(ctx, intent, target, grant, revision); err != nil {
						return fmt.Errorf("terminal grant for seat %s: %w", target.SeatID, err)
					}
				}
				if _, _, err := enrollment.grants.TerminalFence(ctx, grant, revision, intent.OperationID); err != nil {
					if errors.Is(err, hostenroll.ErrTerminalFenceConflict) {
						continue
					}
					return fmt.Errorf("fence terminal grant for seat %s: %w", target.SeatID, err)
				}
			}
			if err := enrollment.verifyTerminalGrantTarget(ctx, intent, target); err != nil {
				return fmt.Errorf("terminal grant fence readback for seat %s: %w", target.SeatID, err)
			}
			fenced = true
			break
		}
		if !fenced {
			return fmt.Errorf("terminal grant for seat %s changed repeatedly during fencing", target.SeatID)
		}
	}
	return enrollment.settleFencedEnrollmentEffects(ctx, epoch, intent)
}

func (enrollment *managedHostEnrollment) settleFencedEnrollmentEffects(ctx context.Context, epoch uint64,
	intent authority.TerminalIntent,
) error {
	ledger, ok := enrollment.fencer.(terminalEnrollmentEffectLedger)
	if !ok {
		return errors.New("terminal grant fencing requires durable enrollment-effect settlement")
	}
	scope := authority.WorkloadScope{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID}
	pending, err := ledger.ListPendingEnrollmentEffects(ctx, scope)
	if err != nil {
		return err
	}
	targets := make(map[string]authority.TerminalTarget, len(intent.Targets))
	for _, target := range intent.Targets {
		if target.InstanceID != "" {
			targets[target.InstanceID] = target
		}
	}
	for _, effect := range pending {
		target, exists := targets[effect.InstanceID]
		if !exists || effect.Epoch > epoch {
			return fmt.Errorf("unmatched enrollment effect %s blocks terminal admission", effect.EffectID)
		}
		if err := enrollment.verifyTerminalGrantTarget(ctx, intent, target); err != nil {
			return fmt.Errorf("pending enrollment effect %s lacks its exact disabled grant fence: %w", effect.EffectID, err)
		}
		if effect.Epoch == epoch {
			_, err = ledger.SettleEnrollmentEffect(ctx, epoch, scope,
				effect.EffectID, effect.InstanceID, effect.Sequence)
		} else {
			verifyFence := func(verifyCtx context.Context) error {
				return enrollment.verifyTerminalGrantTarget(verifyCtx, intent, target)
			}
			_, err = ledger.SettleFencedEnrollmentEffect(ctx, epoch, scope,
				effect.EffectID, effect.InstanceID, effect.Sequence, verifyFence)
		}
		if err != nil {
			return fmt.Errorf("settle terminally fenced enrollment effect %s: %w", effect.EffectID, err)
		}
	}
	pending, err = ledger.ListPendingEnrollmentEffects(ctx, scope)
	if err != nil {
		return err
	}
	if len(pending) != 0 {
		return errors.New("unsettled enrollment effects remain after exact grant fencing")
	}
	return nil
}

grant_proof.text:
func (enrollment *managedHostEnrollment) verifyTerminalGrantTarget(ctx context.Context,
	intent authority.TerminalIntent, target authority.TerminalTarget,
) error {
	if target.InstanceID == "" {
		return nil
	}
	grant, revision, err := enrollment.grants.Read(ctx, target.InstanceID)
	if err != nil {
		return err
	}
	if revision == 0 || !grant.Disabled || grant.TerminalOperationID != intent.OperationID ||
		grant.InstanceID != target.InstanceID || grant.CreateKey != target.HostCreateKey {
		return errors.New("grant is not the exact disabled terminal fence")
	}
	if isTerminalGrantTombstone(grant, target, intent.OperationID) {
		return nil
	}
	if err := enrollment.verifyTerminalGrantBinding(ctx, intent, target, grant, revision); err != nil {
		return err
	}
	return nil
}

// verifyTerminalGrantFence is a read-only proof used before marker commit.
// Every inventory target with an instance ID must have an exact disabled
// grant or create-if-absent tombstone tied to this terminal operation.
func (enrollment *managedHostEnrollment) verifyTerminalGrantFence(ctx context.Context,
	intent authority.TerminalIntent,
) error {
	if enrollment == nil || enrollment.grants == nil || enrollment.members == nil {
		return errors.New("managed terminal grant readback is unavailable")
	}
	if err := enrollment.validateTerminalGrantIntent(intent); err != nil {
		return err
	}
	for _, target := range intent.Targets {
		if err := enrollment.verifyTerminalGrantTarget(ctx, intent, target); err != nil {
			return fmt.Errorf("terminal grant for seat %s: %w", target.SeatID, err)
		}
	}
	return nil
}

grant_verify.text:
func (enrollment *managedHostEnrollment) verifyTerminalGrants(ctx context.Context,
	intent authority.TerminalIntent,
) error {
	if enrollment == nil || enrollment.grants == nil || enrollment.members == nil {
		return errors.New("managed terminal grant readback is unavailable")
	}
	if err := enrollment.validateTerminalGrantIntent(intent); err != nil {
		return err
	}
	if err := enrollment.verifyCurrentTerminalIntent(ctx, intent); err != nil {
		return err
	}
	return enrollment.verifyTerminalGrantFence(ctx, intent)
}

func (enrollment *managedHostEnrollment) verifyCurrentTerminalIntent(ctx context.Context,
	intent authority.TerminalIntent,
) error {
	reader, ok := enrollment.fencer.(authority.TerminalIntentReader)
	if !ok {
		return errors.New("terminal grant readback requires authority marker access")
	}
	entry, err := reader.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID)
	if err != nil {
		return err
	}
	payload, err := protocol.EncodeJSON(intent)
	if err != nil || entry.Sequence == 0 || !bytes.Equal(entry.Payload, payload) {
		return errors.New("terminal grant readback intent differs from the immutable authority marker")
	}
	return nil
}

oci_terminal.text:
func (f *fleet) ReconcileTerminal(ctx context.Context, intent authority.TerminalIntent, markerSeq uint64) (TerminalStatus, error) {
	status := TerminalStatus{Phase: "pending"}
	if err := f.requireTerminalMarker(ctx, intent, markerSeq); err != nil {
		return status, err
	}
	terminated, err := f.inspectTerminalInventory(ctx, intent)
	for _, id := range terminated {
		if writeErr := f.journal.RecordVolumeTermination(ctx, f.config, id); writeErr != nil {
			return status, errors.Join(err, writeErr)
		}
	}
	if err != nil {
		return status, err
	}
	for _, target := range intent.Targets {
		if target.InstanceID != "" {
			settled, err := f.reconcileTerminalInstance(ctx, intent, markerSeq, target)
			if err != nil {
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.InstanceID)
				continue
			}
			settled, err = f.reconcileTerminalBoot(ctx, intent, markerSeq, target)
			if err != nil {
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.BootVolumeID)
			}
		}
		if target.DataVolumeID != "" {
			settled, err := f.reconcileTerminalData(ctx, intent, markerSeq, target)
			if err != nil {
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.DataVolumeID)
			}
		}
	}
	if len(status.Pending) == 0 {
		status.Phase = "complete"
	}
	return status, nil
}

oci_terminal_status.text:
func (f *fleet) InspectTerminalStatus(ctx context.Context, intent authority.TerminalIntent) (TerminalStatus, error) {
	status := TerminalStatus{Phase: TerminalPhasePending}
	if err := f.VerifyTerminalInventorySettled(ctx, intent); err != nil {
		status.Phase = TerminalPhaseHeld
		return status, err
	}
	for _, target := range intent.Targets {
		if target.InstanceID != "" {
			settled, err := f.terminalInstanceSettled(ctx, target.InstanceID)
			if err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.InstanceID)
			} else if err := f.requireTerminalResultSettled(ctx, intent, actionTerminalTerminate, target.InstanceID); err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			settled, err = f.terminalBootSettled(ctx, target)
			if err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.BootVolumeID)
			} else if err := f.requireTerminalResultSettled(ctx, intent, actionTerminalBootDelete, target.BootVolumeID); err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
		}
		if target.DataVolumeID != "" {
			settled, _, err := f.terminalDataSettled(ctx, target.DataVolumeID)
			if err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.DataVolumeID)
			} else if err := f.requireTerminalResultSettled(ctx, intent, actionTerminalDataDelete, target.DataVolumeID); err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
		}
	}
	if len(status.Pending) == 0 {
		status.Phase = TerminalPhaseComplete
	}
	return status, nil
}

placement_store.text:
func NewJetStreamStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, intents AdmittedIntentReader) (Store, error) {
	if !validToken(cell) || js == nil || intents == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("placement store requires cell, JetStream, admitted intent reader and valid replica count")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       stateBucketName,
		Description:  "Durable regional TerraBase placement member state",
		History:      2,
		MaxValueSize: maxStateBytes,
		MaxBytes:     128 << 20,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open placement member state: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("read placement member state status: %w", err)
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("placement state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	return &jetStreamStore{cell: cell, state: kv, intents: intents}, nil
}

func (store *jetStreamStore) ListIntents(ctx context.Context) ([]Intent, error) {
	intents, err := store.intents.ListPlacementIntents(ctx, store.cell)
	if err != nil {
		return nil, err
	}
	if len(intents) > maxIntentCount {
		return nil, errors.New("placement intent listing exceeds its bound")
	}
	seen := make(map[string]struct{}, len(intents))
	for _, intent := range intents {
		if err := intent.Validate(); err != nil {
			return nil, err
		}
		if !validLowerSHA256Digest(intent.PayloadDigest()) {
			return nil, fmt.Errorf("%w: admitted placement intent is missing its canonical committed payload digest", ErrInvalidIntent)
		}
		identity := intent.DatabaseID + "\x00" + intent.PartitionID
		if _, exists := seen[identity]; exists {
			return nil, fmt.Errorf("%w: duplicate database/partition intent %q/%q", ErrInvalidIntent, intent.DatabaseID, intent.PartitionID)
		}
		seen[identity] = struct{}{}
	}
	slices.SortFunc(intents, func(a, b Intent) int {
		if database := strings.Compare(a.DatabaseID, b.DatabaseID); database != 0 {
			return database
		}
		return strings.Compare(a.PartitionID, b.PartitionID)
	})
	return intents, nil
}

placement_read.text:
func (store *jetStreamStore) ListMembers(ctx context.Context, databaseID, partitionID string) ([]VersionedMemberState, error) {
	if !validDatabaseKeyID(databaseID) || !entityid.Valid(partitionID) {
		return nil, fmt.Errorf("%w: database or partition id", ErrInvalidIntent)
	}
	// Every supported region has exactly two fixed seats in this schema.
	result := make([]VersionedMemberState, 0, len(regionsInOrder)*SeatsPerRegion)
	for _, region := range regionsInOrder {
		seats, err := RegionSeatIDs(region)
		if err != nil {
			return nil, err
		}
		for _, seat := range seats {
			member, err := store.ReadMember(ctx, databaseID, partitionID, seat)
			if errors.Is(err, ErrMemberNotFound) {
				continue
			}
			if err != nil {
				return nil, err
			}
			result = append(result, member)
		}
	}
	slices.SortFunc(result, func(a, b VersionedMemberState) int {
		return strings.Compare(a.State.MemberID, b.State.MemberID)
	})
	return result, nil
}

func (store *jetStreamStore) ReadMember(ctx context.Context, databaseID, partitionID, seatID string) (VersionedMemberState, error) {
	if !validDatabaseKeyID(databaseID) || !entityid.Valid(partitionID) ||
		!entityid.Valid(seatID) {
		return VersionedMemberState{}, fmt.Errorf("%w: database, partition, or seat id", ErrInvalidIntent)
	}
	key := memberStateKey(databaseID, partitionID, seatID)
	entry, err := store.state.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return VersionedMemberState{}, ErrMemberNotFound
	}
	if err != nil {
		return VersionedMemberState{}, err
	}
	if entry.Operation() != jetstream.KeyValuePut {
		return VersionedMemberState{}, fmt.Errorf("%w: tombstone at %s", ErrStoreCorrupt, key)
	}
	return decodeMemberState(databaseID, partitionID, seatID, entry.Value(), entry.Revision())
}

func decodeMemberState(databaseID, partitionID, seatID string, data []byte, revision uint64) (VersionedMemberState, error) {
	key := memberStateKey(databaseID, partitionID, seatID)
	var state MemberState
	if len(data) > maxStateBytes || json.Unmarshal(data, &state, json.RejectUnknownMembers(true)) != nil {
		return VersionedMemberState{}, fmt.Errorf("%w: decode %s", ErrStoreCorrupt, key)
	}
	if err := state.Validate(); err != nil || state.DatabaseID != databaseID || state.PartitionID != partitionID ||
		state.MemberID != seatID || memberStateKey(state.DatabaseID, state.PartitionID, state.MemberID) != key {
		return VersionedMemberState{}, fmt.Errorf("%w: invalid state at %s", ErrStoreCorrupt, key)
	}
	return VersionedMemberState{State: state, Revision: revision}, nil
}

placement_cas.text:
func (store *jetStreamStore) CompareAndSwap(ctx context.Context, expected uint64, state MemberState) (uint64, error) {
	if err := state.Validate(); err != nil {
		return 0, err
	}
	data, err := json.Marshal(state)
	if err != nil {
		return 0, err
	}
	if len(data) > maxStateBytes {
		return 0, errors.New("placement member state exceeds size bound")
	}
	key := memberStateKey(state.DatabaseID, state.PartitionID, state.MemberID)
	var revision uint64
	if expected == 0 {
		revision, err = store.state.Create(ctx, key, data)
	} else {
		revision, err = store.state.Update(ctx, key, data, expected)
	}
	if err != nil {
		if errors.Is(err, jetstream.ErrKeyExists) || errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return 0, fmt.Errorf("%w: %v", ErrStoreConflict, err)
		}
		return 0, err
	}
	return revision, nil
}

placement_summary.text:
func Summarize(ctx context.Context, store Store) (observability.PlacementView, error) {
	if store == nil {
		return observability.PlacementView{}, errors.New("placement summary requires a store")
	}
	intents, err := store.ListIntents(ctx)
	if err != nil {
		return observability.PlacementView{}, err
	}
	view := observability.PlacementView{StageCounts: map[string]int{}}
	for index, intent := range intents {
		if index >= maxSummarizedPartitions {
			view.Truncated = true
			break
		}
		members, err := store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			return observability.PlacementView{}, err
		}
		database := summarizePartition(intent, members)
		if _, err := store.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			database.Terminal = true
		} else if !errors.Is(err, authority.ErrNotFound) {
			return observability.PlacementView{}, err
		}
		for stage, count := range database.Stages {
			view.StageCounts[stage] += count
		}
		view.Databases = append(view.Databases, database)
	}
	return view, nil
}

func summarizePartition(intent Intent, members []VersionedMemberState) observability.DatabaseView {
	database := observability.DatabaseView{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
		Generation: intent.Generation, DesiredSeats: len(intent.CanonicalRoster.Rows), Stages: map[string]int{},
		Readiness: "unknown", ReadinessReason: "current native root task and member readiness source is unavailable"}
	var latest *ManagedRuntimeTarget
	for index := range members {
		state := members[index].State
		stage := string(state.Stage)
		database.Stages[stage]++
		database.Members = append(database.Members, observability.MemberView{SeatID: state.MemberID,
			Stage: stage, HostNode: state.HostNode, FailureDomain: state.FailureDomain,
			UpdatePhase: string(state.ManagedRuntimeTarget.Phase), UpdatedAt: state.UpdatedAt})
		target := &members[index].State.ManagedRuntimeTarget
		if target.OperationID != "" && (latest == nil || target.PreparedAt.After(latest.PreparedAt)) {
			latest = target
		}
	}
	if latest == nil {
		return database
	}
	// A managed update operation targets its own seats (one canary per
	// operation), so its progress is over the seats it targets, not every
	// placement seat: otherwise a finished update reads as stalled at 1/2.
	rollout := &observability.RolloutView{OperationID: latest.OperationID, ArtifactDigest: latest.ArtifactDigest,
		Phases: map[string]int{}}
	for _, member := range members {
		target := member.State.ManagedRuntimeTarget
		if target.OperationID != latest.OperationID {
			continue
		}
		rollout.Seats++
		rollout.Phases[string(target.Phase)]++
		if target.Phase == ManagedUpdateSeatCanaryServing && member.State.Stage == StageServing {
			rollout.Completed++
		}
	}
	database.Rollout = rollout
	return database
}

terra_placement.text:
func terraBasePlacement(profile WorkloadProfile, replicas int, candidates []placement.WorkloadHost, previous []placement.Assignment,
	address func(string) string,
) ([]placement.WorkloadHost, []placement.Assignment, error) {
	if members, err := terrabase.ParseProfile(profile.Env); err == nil {
		if replicas != len(members.Peers) {
			return nil, nil, fmt.Errorf("terrabase release asks for %d members, %s lists %d", replicas, terrabase.EnvPeers, len(members.Peers))
		}
		candidates = slices.DeleteFunc(slices.Clone(candidates), func(candidate placement.WorkloadHost) bool {
			var granted string
			if address != nil {
				granted = address(candidate.Node)
			}
			_, listed := members.Member(candidate.Node, granted)
			return !listed
		})
	}
	previous = slices.Clone(previous)
	for i := range previous {
		previous[i].Pending = true
	}
	return candidates, previous, nil
}

validate_profiles.text:
func validateWorkloadProfiles(cell string, profiles map[string]WorkloadProfile) error {
	for role, profile := range profiles {
		if !grantToken.MatchString(role) || profile.Resources.CPU <= 0 || profile.Resources.CPU > 4096 ||
			profile.Resources.MemoryBytes <= 0 || profile.Resources.MemoryBytes > 1<<50 ||
			profile.Resources.DiskBytes <= 0 || profile.Resources.DiskBytes > 1<<50 {
			return fmt.Errorf("invalid workload resource profile for role %q", role)
		}
		if len(profile.Args) > 64 || len(profile.Env) > 64 {
			return fmt.Errorf("workload profile for %q exceeds argument or environment limit", role)
		}
		for _, arg := range profile.Args {
			if len(arg) > 4096 {
				return fmt.Errorf("workload argument for %q is too long", role)
			}
		}
		for key, value := range profile.Env {
			if key == "" || len(value) > 4096 {
				return fmt.Errorf("workload environment for %q is invalid", role)
			}
		}
		for key := range profile.Secrets {
			if role == terrabase.Role && !vaultsecret.FileKey(key) {
				return fmt.Errorf("workload profile for %q takes only Vault secret files (keys ending in _FILE)", role)
			}
			if roleidentity.Reserved(role, key) {
				return fmt.Errorf("workload profile for %q: the host sets %s for its NATS identity", role, key)
			}
		}
		for key := range profile.Env {
			if roleidentity.Reserved(role, key) {
				return fmt.Errorf("workload profile for %q: the host sets %s for its NATS identity", role, key)
			}
		}
		if err := vaultsecret.ValidateRefs(cell, role, profile.Secrets, profile.Env); err != nil {
			return fmt.Errorf("workload profile for %q: %w", role, err)
		}
		// Secret names start with the role, so a longer role would share them.
		for other := range profiles {
			if len(profile.Secrets) != 0 && strings.HasPrefix(other, role+"-") {
				return fmt.Errorf("workload profile for %q names Vault secrets, so no role may extend its name (%q)", role, other)
			}
		}
		// A terrabase profile with settings configures the C# TerraBase
		// binary. Arguments would override the host-owned settings.
		if role == terrabase.Role && len(profile.Env) != 0 {
			if _, err := terrabase.ParseProfile(profile.Env); err != nil {
				return fmt.Errorf("workload profile for %q: %w", role, err)
			}
			if len(profile.Args) != 0 {
				return fmt.Errorf("workload profile for %q sets TerraBase settings only through env", role)
			}
		}
		// The ts-auth profile is signed and readable: it must hold every
		// setting and name its secrets, which hosts read from the Vault.
		if role == tsauth.Role {
			if err := tsauth.ValidateProfile(cell, profile.Args, profile.Env, profile.Secrets); err != nil {
				return fmt.Errorf("workload profile for %q: %w", role, err)
			}
			if err := tsauth.ValidateMembers(profile.Env, profiles[terrabase.Role].Env); err != nil {
				return fmt.Errorf("workload profile for %q: %w", role, err)
			}
		}
	}
	return nil
}

