func PlanWorkload(request WorkloadRequest) ([]Assignment, error) {
	if !validToken(request.Cell) || !validToken(request.Role) || request.Replicas < 0 || request.Replicas > 1024 ||
		request.MaxPerFailureDomain < 0 || !positive(request.Request) {
		return nil, fmt.Errorf("%w: cell, role, replica count or resource request", ErrInvalidWorkload)
	}

	hosts := make(map[string]WorkloadHost, len(request.Hosts))
	for _, candidate := range request.Hosts {
		if !validToken(candidate.Cell) || !validToken(candidate.Node) || candidate.Cell != request.Cell ||
			candidate.FailureDomain != "" && !validToken(candidate.FailureDomain) ||
			!nonNegative(candidate.Capacity) || !nonNegative(candidate.Allocated) {
			return nil, fmt.Errorf("%w: malformed host %q", ErrInvalidWorkload, candidate.Node)
		}
		if _, exists := hosts[candidate.Node]; exists {
			return nil, fmt.Errorf("%w: duplicate host %q", ErrInvalidWorkload, candidate.Node)
		}
		hosts[candidate.Node] = candidate
	}

	previousNodes := make(map[string]Assignment, len(request.Previous))
	previous := make([]Assignment, 0, len(request.Previous))
	for _, assignment := range request.Previous {
		if assignment.Withdrawn {
			continue
		}
		if !validToken(assignment.Node) || assignment.Role != request.Role || assignment.Ordinal < 0 {
			return nil, fmt.Errorf("%w: malformed previous assignment", ErrInvalidWorkload)
		}
		if _, exists := previousNodes[assignment.Node]; exists {
			return nil, fmt.Errorf("%w: duplicate previous node %q", ErrInvalidWorkload, assignment.Node)
		}
		previousNodes[assignment.Node] = assignment
		previous = append(previous, assignment)
	}
	slices.SortFunc(previous, func(a, b Assignment) int {
		if ordinal := cmp.Compare(a.Ordinal, b.Ordinal); ordinal != 0 {
			return ordinal
		}
		return cmp.Compare(a.Node, b.Node)
	})

	active := make([]Assignment, 0, request.Replicas)
	usedNodes := make(map[string]struct{}, request.Replicas)
	quarantined := make(map[string]struct{})
	domainCounts := make(map[string]int)
	for _, old := range previous {
		candidate, exists := hosts[old.Node]
		if exists && schedulable(candidate, request.Role) && fits(candidate, request.Request) && (old.Ready || old.Pending) {
			if len(active) < request.Replicas && !domainFull(request, domainCounts, candidate) {
				old.Ordinal = len(active)
				active = append(active, old)
				usedNodes[old.Node] = struct{}{}
				domainCounts[candidate.FailureDomain]++
				continue
			}
		} else if exists {
			// A host with a failed workload is not immediately selected as its own
			// replacement during the same reconciliation.
			quarantined[old.Node] = struct{}{}
		}
	}

	for len(active) < request.Replicas {
		best, ok := chooseHost(request, hosts, usedNodes, quarantined, active, domainCounts)
		if !ok {
			return nil, fmt.Errorf("%w: placed %d of %d replicas", ErrInsufficientCapacity, len(active), request.Replicas)
		}
		active = append(active, Assignment{
			Node:    best.Node,
			Role:    request.Role,
			Ordinal: len(active),
			Pending: true,
		})
		usedNodes[best.Node] = struct{}{}
		domainCounts[best.FailureDomain]++
	}

	result := slices.Clone(active)
	kept := make(map[string]struct{}, len(active))
	for _, assignment := range active {
		kept[assignment.Node] = struct{}{}
	}
	withdrawn := make([]Assignment, 0, len(previous))
	for _, old := range previous {
		if _, exists := kept[old.Node]; exists {
			continue

release_current.text:
func releaseCurrent(statuses []host.HostStatus, desired []host.Desired, role, environment string) (string, uint64, error) {
	current := ""
	for _, status := range statuses {
		for _, report := range status.Reports {
			if report.Role != role || report.Environment != environment || report.State != "running" {
				continue
			}
			if current != "" && report.Digest != current {
				return "", 0, fmt.Errorf("%s replicas run %s and %s: %w", role, current, report.Digest, errReplicasDisagree)
			}
			current = report.Digest
		}
	}
	return current, nextReleaseGeneration(desired), nil
}

// nextReleaseGeneration is the next intent generation of a role, above every
// committed desired of it (releaseCurrent).
func nextReleaseGeneration(desired []host.Desired) uint64 {
	highest := uint64(0)
	for _, d := range desired {
		highest = max(highest, d.Generation)
	}
	if release := workload.ReleaseOf(highest); release > 0 {
		highest = release
	}
	return highest + 1
}

unchanged.text:
func unchanged(receipt delivery.Receipt) bool {
	return receipt.Status == "rejected" || receipt.Status == "held" && !heldAfterPlanning(receipt)
}

held_after_planning.text:
func heldAfterPlanning(receipt delivery.Receipt) bool {
	return !strings.HasPrefix(receipt.Error, delivery.PlannerRefusedHold)
}

release_command.text:
func operatorTerraBaseRelease(ctx context.Context, cfg Config, runtime *natscell.Runtime, options terraBaseReleaseOptions, output io.Writer) error {
	// A progress line that cannot be written must not read as a failed gate.
	progress := &stickyWriter{writer: output}
	err := releaseTerraBase(ctx, cfg, runtime, options, progress)
	return errors.Join(err, progress.err)
}

func releaseTerraBase(ctx context.Context, cfg Config, runtime *natscell.Runtime, options terraBaseReleaseOptions, output io.Writer) error {
	digest, err := terrabase.VerifyRelease(options.Binary, options.Checksum)
	if err != nil {
		return err
	}
	profile, err := readReleaseProfile(options.Profile)
	if err != nil {
		return err
	}
	members, err := terrabase.ParseProfile(profile.Env)
	if err != nil {
		return err
	}
	return releaseNative(ctx, cfg, runtime, nativeRelease{Role: terrabase.Role, Repository: terrabase.Repository,
		Digest: digest, Replicas: len(members.Peers), Profile: profile}, options, output)
}

release_native.text:
func releaseNative(ctx context.Context, cfg Config, runtime *natscell.Runtime, target nativeRelease, options terraBaseReleaseOptions, output io.Writer) error {
	if options.Wait == 0 {
		options.Wait = rollout.ObservationBudget
	}
	tree, err := release.SourceTreeDigest(ctx, options.SourceCheckout, options.Commit)
	if err != nil {
		return err
	}
	deadline := time.Now().UTC().Add(min(options.Wait, rollout.ObservationBudget))
	deployer, err := operatorNativeDeployer(ctx, cfg, runtime, deadline)
	if err != nil {
		return err
	}
	previous, generation, err := deployer.current(ctx, target.Role, options.Environment)
	if err != nil {
		return err
	}
	record, err := pushArtifact(ctx, cfg, runtime, options.Binary, delivery.ArtifactClaimRequest{
		Source: delivery.ArtifactSource{Repository: target.Repository, Commit: options.Commit, TreeDigest: tree},
		Cell:   cfg.NATS.Cell, Role: target.Role, Environment: options.Environment,
	})
	if err != nil {
		return err
	}
	if record.Digest != target.Digest {
		return fmt.Errorf("controller admitted %s, the release pins %s", record.Digest, target.Digest)
	}
	if err := printJSON(output, terraBaseReleaseStep{Step: "artifact", Digest: record.Digest, Previous: previous}); err != nil {
		return err
	}
	return deployer.roll(ctx, nativeIntent(record, target, generation), options.Wait, output)
}

func operatorNativeDeployer(ctx context.Context, cfg Config, runtime *natscell.Runtime, deadline time.Time) (nativeDeployer, error) {
	setupCtx, stopSetup := context.WithTimeout(ctx, operatorSubmitSetupTimeout)
	defer stopSetup()
	reader, err := retryOperatorMetadata(setupCtx, func(attempt context.Context) (*host.Reader, error) {
		return operatorHostReader(attempt, cfg, runtime)
	})
	if err != nil {
		return nativeDeployer{}, err
	}
	service, err := retryOperatorMetadata(setupCtx, func(attempt context.Context) (*delivery.Service, error) {
		return operatorService(attempt, cfg, runtime, true)
	})
	if err != nil {
		return nativeDeployer{}, err
	}
	return nativeDeployer{service: service, hosts: reader,
		prepare: func(ctx context.Context, intent delivery.Intent, recoveryOf, resumeOf string) (delivery.Intent, *nativeRollbackTarget, error) {
			if intent.SchemaVersion == 0 {
				intent.SchemaVersion = delivery.SchemaVersion
			}
			if intent.Cell == "" {
				intent.Cell = cfg.NATS.Cell
			}
			if intent.OperationID == "" {
				intent.OperationID = entityid.New()
			}
			if intent.AuthorityEpoch == 0 {
				readCtx, stopRead := context.WithTimeout(ctx, operatorSubmitSetupTimeout)
				epoch, err := observeOperatorAuthority(readCtx, func(attempt context.Context) (authority.Snapshot, error) {
					return authority.Observe(attempt, runtime.JetStream(), cfg.NATS.Cell)
				})
				stopRead()
				if err != nil {
					return intent, nil, err
				}
				intent.AuthorityEpoch = epoch
			}

release_verify.text:
func VerifyRelease(binaryPath, checksumPath string) (string, error) {
	return VerifyAsset(binaryPath, checksumPath, assetRE)
}

// VerifyAsset is VerifyRelease for any single-file release executable whose
// asset name matches asset, such as ts-auth-linux-arm64.
func VerifyAsset(binaryPath, checksumPath string, asset *regexp.Regexp) (string, error) {
	name := filepath.Base(binaryPath)
	if !asset.MatchString(name) {
		return "", fmt.Errorf("release executable %q is not one of %s", name, asset)
	}
	checksum, err := os.ReadFile(checksumPath)
	if err != nil {
		return "", err
	}
	fields := strings.Fields(string(checksum))
	if len(fields) != 2 || bytes.Count(checksum, []byte("\n")) > 1 || strings.TrimPrefix(fields[1], "*") != name ||
		len(fields[0]) != 64 || strings.ToLower(fields[0]) != fields[0] {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	if _, err := hex.DecodeString(fields[0]); err != nil {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	file, err := os.Open(binaryPath)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	// The asset name is the architecture the hosts run: an executable built
	// for another machine would otherwise fail only once it reached them.
	var header elf.Header64
	if err := binary.Read(io.TeeReader(file, hash), binary.LittleEndian, &header); err != nil || string(header.Ident[:4]) != elf.ELFMAG {
		return "", fmt.Errorf("%s is not an ELF executable", binaryPath)
	}
	if elf.Class(header.Ident[elf.EI_CLASS]) != elf.ELFCLASS64 || elf.Data(header.Ident[elf.EI_DATA]) != elf.ELFDATA2LSB {
		return "", fmt.Errorf("%s is not a 64-bit little-endian ELF executable", binaryPath)
	}
	want := map[string]elf.Machine{"amd64": elf.EM_X86_64, "arm64": elf.EM_AARCH64}[name[strings.LastIndexByte(name, '-')+1:]]
	if got := elf.Machine(header.Machine); got != want {
		return "", fmt.Errorf("%s must be built for %v, found %v", name, want, got)
	}
	size, err := io.Copy(hash, io.LimitReader(file, maxBinaryBytes))
	if err != nil {
		return "", err
	}
	if size+int64(binary.Size(header)) > maxBinaryBytes {
		return "", errors.New("release executable exceeds the artifact admission limit")
	}
	if digest := hex.EncodeToString(hash.Sum(nil)); digest != fields[0] {
		return "", fmt.Errorf("%s has SHA-256 %s, its release checksum says %s", name, digest, fields[0])
	}
	return fields[0], nil
}

health_http.text:
func Healthy(ctx context.Context, adminPort int) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(adminPort)+"/healthz", nil)
	if err != nil {
		return err
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase health: %w", err)
	}
	defer response.Body.Close()
	var body struct {
		Status string `json:"status"`
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, 4096))
	if err == nil && response.StatusCode == http.StatusOK {
		err = json.Unmarshal(data, &body)
	}
	if err != nil || response.StatusCode != http.StatusOK || body.Status != "ok" {
		return fmt.Errorf("terrabase health: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

qualification_gate.text:
// Qualifying reports whether this run is a T2 qualification run.
func Qualifying() bool { return os.Getenv(Env) == QualificationTier }

// Integration marks a T1 test: a multi-process lab or a slow end-to-end
// contract whose invariants T0 already covers with a single-process test.
// It skips under go test -short.
func Integration(t testing.TB) {
	t.Helper()
	if testing.Short() {
		t.Skip("integration tier: runs without -short on pushes to develop and main")
	}
}

// Qualification marks a T2 test that needs real infrastructure named by
// environment variables, and returns their values in order. When any of them
// is unset or empty the test skips, except in a qualification run, where it
// fails: the fixture the gate promised is missing.
func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

// Unavailable reports that a T2 fixture is missing for a reason the caller
// determined itself, such as an opt-in that needs one of several variables.
// It skips the test, or fails it in a qualification run.
func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}

