func (f *fleet) EnsureHost(ctx context.Context, request EnsureRequest) (Instance, error) {
	if !validCreateKey(request.CreateKey) || !slices.Contains(f.config.FaultDomains, request.FaultDomain) {
		return Instance{}, errors.New("OCI host launch has an invalid create key or unsupported fault domain")
	}
	if !f.memberName(request.Name, false) {
		return Instance{}, fmt.Errorf("OCI host launch name %q is not a member name of this cell", request.Name)
	}
	if !validManagedPrivateIP(request.PrivateIP) {
		return Instance{}, errors.New("OCI host launch requires a signed private IPv4 address")
	}
	if request.Shape != f.config.Shape || !validComputeProfile(request.Shape, request.WholeOCPUs,
		request.MemoryInGBs, request.PlacementProfileDigest, request.PlacementGeneration) {
		return Instance{}, ErrPlacementProfileMismatch
	}
	choice, err := f.launchImage(ctx, request.CreateKey)
	if err != nil {
		return Instance{}, err
	}
	image := choice.image
	descriptor, err := f.hostBootDescriptor(request, image)
	if err != nil {
		return Instance{}, fmt.Errorf("%w: %v", ErrHostBootBindingMismatch, err)
	}
	descriptorWire, err := descriptor.CanonicalBytes()
	if err != nil {
		return Instance{}, fmt.Errorf("%w: encode descriptor: %v", ErrHostBootBindingMismatch, err)
	}
	descriptorDigest, err := descriptor.Digest()
	if err != nil {
		return Instance{}, fmt.Errorf("%w: digest descriptor: %v", ErrHostBootBindingMismatch, err)
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return Instance{}, err
	}
	release, err := f.beginActiveWorkloadEffect(ctx, epoch, descriptor.DatabaseID, descriptor.PartitionID)
	if err != nil {
		return Instance{}, err
	}
	defer release()
	if err := f.verifyLaunchScope(ctx, descriptor, request.CreateKey); err != nil {
		return Instance{}, err
	}
	intent := f.intent(actionLaunch, request.CreateKey, "", request.CreateKey, "", request.FaultDomain, "")
	intent.Shape = request.Shape
	intent.PrivateIP = request.PrivateIP
	intent.WholeOCPUs = request.WholeOCPUs
	intent.MemoryInGBs = request.MemoryInGBs
	intent.PlacementProfileDigest = request.PlacementProfileDigest
	intent.PlacementGeneration = request.PlacementGeneration
	intent.ImageID = image
	intent.BootDescriptor = string(descriptorWire)
	intent.BootDescriptorSHA256 = descriptorDigest
	if err := f.recordIntent(ctx, epoch, intent); err != nil {
		return Instance{}, err
	}
	priorResult, hasPriorResult, err := f.journal.GetResult(ctx, intent)
	if err != nil {
		return Instance{}, fmt.Errorf("read OCI host operation result: %w", err)
	}
	operationIntent := priorResult.Intent
	if operationIntent.CreatedAt.IsZero() {
		operationIntent = intent
	}
	cloud, identity, found, err := f.findByCreateKey(ctx, request.CreateKey)
	if err != nil {
		if hasPriorResult && !priorResult.Unknown && isNotFound(err) {
			return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the previously confirmed instance is missing")
		}

grant_terminal_cas.text:
func (store *GrantStore) TerminalFence(ctx context.Context, expected Grant, expectedRevision uint64,
	operationID string,
) (Grant, uint64, error) {
	if store == nil || store.kv == nil || expected.SchemaVersion != 1 || expected.InstanceID == "" ||
		expected.CreateKey == "" || !validTerminalOperationID(operationID) {
		return Grant{}, 0, errors.New("terminal enrollment grant fence identity is invalid")
	}
	if expectedRevision == 0 {
		if expected.DescriptorSHA256 != "" || len(expected.Request) != 0 || len(expected.Response) != 0 ||
			expected.Disabled || expected.OwnerToken != "" || !expected.LeaseUntil.IsZero() ||
			len(expected.RenewalRequest) != 0 || len(expected.RenewalResponse) != 0 ||
			expected.RenewalToken != "" || !expected.RenewalLeaseUntil.IsZero() || expected.TerminalOperationID != "" || expected.IdentityResetOperationID != "" || expected.SwarmMembership != nil {
			return Grant{}, 0, errors.New("absent terminal grant fence contains enrollment state")
		}
		tombstone := Grant{SchemaVersion: 1, InstanceID: expected.InstanceID,
			CreateKey: expected.CreateKey, Disabled: true, TerminalOperationID: operationID}
		wire, err := json.Marshal(tombstone)
		if err != nil {
			return Grant{}, 0, err
		}
		revision, err := store.kv.Create(ctx, grantKey(expected.InstanceID), wire)
		if err == nil {
			return tombstone, revision, nil
		}
		if !errors.Is(err, jetstream.ErrKeyExists) {
			return Grant{}, 0, fmt.Errorf("create terminal enrollment grant tombstone: %w", err)
		}
		current, revision, readErr := store.Read(ctx, expected.InstanceID)
		if readErr != nil {
			return Grant{}, 0, readErr
		}
		if isTerminalTombstone(current, expected.InstanceID, expected.CreateKey, operationID) {
			return current, revision, nil
		}
		return Grant{}, 0, ErrTerminalFenceConflict
	}
	if isTerminalTombstone(expected, expected.InstanceID, expected.CreateKey, operationID) {
		current, revision, err := store.Read(ctx, expected.InstanceID)
		if err != nil {
			return Grant{}, 0, err
		}
		if revision == expectedRevision && isTerminalTombstone(current, expected.InstanceID,
			expected.CreateKey, operationID) && sameGrant(current, expected) {
			return current, revision, nil
		}
		return Grant{}, 0, ErrTerminalFenceConflict
	}

	if len(expected.Request) == 0 || len(expected.DescriptorSHA256) != 64 ||
		expected.TerminalOperationID != "" && expected.TerminalOperationID != operationID {
		return Grant{}, 0, errors.New("existing terminal grant fence lacks exact grant pins")
	}
	current, revision, err := store.Read(ctx, expected.InstanceID)
	if err != nil {
		return Grant{}, 0, err
	}
	if isTerminalTombstone(current, expected.InstanceID, expected.CreateKey, operationID) {
		if current.DescriptorSHA256 == expected.DescriptorSHA256 && bytes.Equal(current.Request, expected.Request) {
			return current, revision, nil
		}
		return Grant{}, 0, ErrTerminalFenceConflict
	}
	if current.Disabled && current.TerminalOperationID == operationID &&
		current.InstanceID == expected.InstanceID && current.CreateKey == expected.CreateKey &&
		current.DescriptorSHA256 == expected.DescriptorSHA256 && bytes.Equal(current.Request, expected.Request) {
		return current, revision, nil
	}
	if revision != expectedRevision || !sameGrant(current, expected) {
		return Grant{}, 0, ErrTerminalFenceConflict
	}
	current.Disabled = true
	current.TerminalOperationID = operationID
	wire, err := json.Marshal(current)
	if err != nil {
		return Grant{}, 0, err
	}
	nextRevision, err := store.kv.Update(ctx, grantKey(expected.InstanceID), wire, expectedRevision)
	if err == nil {
		return current, nextRevision, nil
	}
	if !errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return Grant{}, 0, fmt.Errorf("disable terminal enrollment grant: %w", err)
	}
	current, revision, readErr := store.Read(ctx, expected.InstanceID)
	if readErr != nil {
		return Grant{}, 0, readErr
	}
	if isTerminalTombstone(current, expected.InstanceID, expected.CreateKey, operationID) &&
		current.DescriptorSHA256 == expected.DescriptorSHA256 && bytes.Equal(current.Request, expected.Request) {
		return current, revision, nil
	}
	return Grant{}, 0, ErrTerminalFenceConflict
}

